ette policy: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/cNdiPqExPKs/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2020-05-17T18:00:16Z","viewCount":244836,"durationSeconds":2552,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
